def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    def ll(Z):
        A = np.column_stack([S, Z]) if Z is not None and Z.size else S
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - mu)); b += step
            if np.abs(step).max() < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    cols = lambda L: X[:, L] if L else None
    def pv(l1, l0, df=1): return stats.chi2.sf(max(2 * (l1 - l0), 0), df)
    def cluster(j):
        c = {j}; fr = {j}
        for _ in range(2):
            fr = {k for i in fr for k in range(p) if abs(R[i, k]) >= 0.6} - c; c |= fr
        return sorted(c)
    sel = []
    while len(sel) < MAX_DRIVERS:
        base = ll(cols(sel)); best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l = ll(cols(sel + [j]))
            if best is None or l > best[0]: best = (l, j)
        if best is None: break
        alpha = (0.25 if not sel else 0.05) / p
        if pv(best[0], base) >= alpha: break
        cl = [k for k in cluster(best[1]) if not any(abs(R[k, s]) >= 0.6 for s in sel)]
        if len(cl) > 1:
            lls = {k: ll(cols(sel + [k])) for k in cl}
            cand = [k for k in cl if lls[k] >= best[0] - 2]
            def loss(k):
                return sum(max(ll(cols(sel + [k, m])) - lls[k], 0) for m in cl if m != k)
            pick = min(cand, key=loss)
        else: pick = best[1]
        sel.append(pick)
    changed = True
    while changed and len(sel) > 1:
        changed = False; full = ll(cols(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if pv(full, ll(cols(rest))) >= 0.05 / p: sel = rest; changed = True; break
    prods = []; npair = p * (p + 1) // 2
    base_cols = list(sel)
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(base_cols + [a, b]))
            l0 = ll(cols(mains)); pr = (X[:, a] * X[:, b])[:, None]
            l1 = ll(np.column_stack([X[:, mains], pr]))
            pval = pv(l1, l0)
            if pval < 0.002 / npair: prods.append((pval, a, b))
    prods.sort(); chosen = []
    for _, a, b in prods:
        if len(chosen) < 2 and not any({a, b} & {c, d} for c, d in chosen): chosen.append((a, b))
    drivers = list(sel)
    for a, b in chosen:
        for k in (a, b):
            if k not in drivers: drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    colset = sorted(set(sel) | {k for a, b in chosen for k in (a, b)})
    return Design(drivers=tuple(ids[k] for k in drivers), columns=tuple(ids[k] for k in colset),
                  products=tuple((ids[a], ids[b]) for a, b in chosen), loadings={})

